import cues from '../../audio/space_duel/cues.json';
import {createTimeline} from '../timeline';

/**
 * The space_duel timeline, generated by tools/build_space_audio.py from
 * audio/space_duel/story.json. Keys are story events ("clash1", "disarm") and
 * narration edges ("n14.start", "n14.end").
 */
type Line = {start: number; end: number; voice: string; text: string};
const lines = cues.lines as Record<string, Line>;

const times: Record<string, number> = {...cues.events};
for (const [id, line] of Object.entries(lines)) {
  times[`${id}.start`] = line.start;
  times[`${id}.end`] = line.end;
}

export type Cue = keyof typeof cues.events | `${keyof typeof cues.lines}.${'start' | 'end'}`;

export const timeline = createTimeline<Cue>(times as Record<Cue, number>, cues.bpm);
export const {at, syncTo, playUntil, beat} = timeline;
export const duration = cues.duration;

/** Narration and alien lines in time order. */
export const narration = Object.entries(lines)
  .map(([id, line]) => ({id, ...line}))
  .sort((a, b) => a.start - b.start);
